	request, err := caps.ConversionRequest.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.RejectOutput{}, err
	}
	if request.Status != schema.ConversionRequestStatus("pending") {
		return capabilities.RejectOutput{}, &capabilities.BusinessError{Code: "conversion_request.reject.invalid_state"}
