	if lead.Status != schema.LeadStatus("qualified") {
		return capabilities.RejectOutput{}, &capabilities.BusinessError{Code: "conversion_request.reject.lead_state_conflict"}
	}
	now := time.Now().UTC()
	principal := caps.Execution.Principal()
	updatedRequest, err := caps.ConversionRequest.ConditionalUpdate(ctx, data.NewConversionRequestUpdate(request.ID).
		SetStatus(schema.ConversionRequestStatus("rejected")).
		SetRejectionReason(input.RejectionReason).
