		RequireStatusEqual(schema.ConversionRequestStatus("pending"), "conversion_request.reject.conflict").
		WithExpectedUpdatedAt(request.UpdatedAt))
	if err != nil {
		return capabilities.RejectOutput{}, err
	}
	company := lead.CompanyName
	reason := input.RejectionReason
	notificationID, err := caps.Notifications.Dispatch(ctx, capabilities.RejectNotificationIntent{
		EventType:        "lead.conversion_rejected",
		SourceEventID:    "conversion-rejected:" + string(request.ID),
		RecipientUserIDs: []string{principal.UserID},
		SubjectObjectKey: "lead",
		SubjectRecordID:  string(lead.ID),
		SubjectVersion:   updatedRequest.UpdatedAt,
		DedupeKey:        "conversion-rejected:" + string(request.ID),
		GroupKey:         "lead:" + string(lead.ID),
		OccurredAt:       now,
		Variables: []capabilities.RejectNotificationVariable{
			{Key: "company_name", StringValue: &company},
			{Key: "rejection_reason", StringValue: &reason},
		},
	})
	if err != nil {
		return capabilities.RejectOutput{}, err
	}
	if updatedRequest.ID == "" || notificationID == "" {
		return capabilities.RejectOutput{}, &capabilities.BusinessError{Code: "conversion_request.reject.empty_effect"}
	}
	return capabilities.RejectOutput{}, nil
}
