func RequestConversion(ctx context.Context, caps capabilities.RequestConversionCapabilities, input capabilities.RequestConversionInput) (capabilities.RequestConversionOutput, error) {
	_ = input
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if lead.Status != schema.LeadStatus("qualified") {
		return capabilities.RequestConversionOutput{}, &capabilities.BusinessError{Code: "lead.request_conversion.invalid_state"}
	}
	direct, err := amountBelowThreshold(lead.EstimatedAmount)
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if !direct {
		createdRequest, err := caps.ConversionRequest.Create(ctx, schema.CreateConversionRequest{
			AmountSnapshot:    schema.ConversionRequestAmountSnapshot(lead.EstimatedAmount),
			LeadID:            schema.NewConversionRequestLeadIDReference(lead.ID),
			Status:            schema.ConversionRequestStatus("pending"),
			ThresholdSnapshot: schema.ConversionRequestThresholdSnapshot(conversionThreshold),
		})
		if err != nil {
			return capabilities.RequestConversionOutput{}, err
		}
		if createdRequest.ID == "" {
			return capabilities.RequestConversionOutput{}, &capabilities.BusinessError{Code: "lead.request_conversion.empty_request"}
		}
		return capabilities.RequestConversionOutput{}, nil
	}
	createdCustomer, err := caps.Customer.Create(ctx, schema.CreateCustomer{
		Amount:       schema.CustomerAmount(lead.EstimatedAmount),
		CompanyName:  lead.CompanyName,
		ContactName:  lead.ContactName,
		Source:       schema.CustomerSource(lead.Source),
		SourceLeadID: schema.NewCustomerSourceLeadIDReference(lead.ID),
	})
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if createdCustomer.ID == "" {
		return capabilities.RequestConversionOutput{}, &capabilities.BusinessError{Code: "lead.request_conversion.empty_customer"}
	}
	mutation := data.NewLeadUpdate(lead.ID).
		SetStatus(schema.LeadStatus("converted")).
		SetStatusChangedAt(time.Now().UTC()).
		RequireStatusEqual(schema.LeadStatus("qualified"), "lead.request_conversion.conflict").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	updatedLead, err := caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if updatedLead.ID == "" {
		return capabilities.RequestConversionOutput{}, &capabilities.BusinessError{Code: "lead.request_conversion.empty_lead"}
	}
	return capabilities.RequestConversionOutput{}, nil
}
