	ErrLeaseLost          = errors.New("identity authoring lease lost")
	ErrReceiptUnavailable = errors.New("identity authoring receipt unavailable")
)

const defaultLeaseTTL = 30 * time.Second

type Service struct {
	repository Repository
	now        func() time.Time
	newID      func() string
}

func NewService(repository Repository, now func() time.Time, newID func() string) *Service {
	if now == nil {
		now = func() time.Time { return time.Now().UTC() }
	}
	if newID == nil {
		newID = requestcontext.NewRequestID
	}
	return &Service{repository: repository, now: now, newID: newID}
}

func (s *Service) ExecuteUpsert(
	ctx context.Context,
	request UpsertRequest,
	principal identitymodel.Principal,
	authorize Authorize,
	current CurrentResource,
	execute Execute,
) (ExecutionResult, error) {
	request.CapabilityKey = strings.TrimSpace(request.CapabilityKey)
	request.ResourceID = strings.TrimSpace(request.ResourceID)
	request.BuilderTaskID = strings.TrimSpace(request.BuilderTaskID)
	request.IdempotencyKey = strings.TrimSpace(request.IdempotencyKey)
	request.ExpectedResourceHash = strings.TrimSpace(request.ExpectedResourceHash)
	if authorize == nil || current == nil || execute == nil {
		return ExecutionResult{}, apperror.New(apperror.KindUnavailable, "backend.authoring.owner_contract_unavailable", nil, nil)
	}
	if err := authorize(); err != nil {
		return ExecutionResult{}, err
	}
	// Idempotency-Key is also used by lifecycle command routes. A direct
	// authoring envelope is selected only by its builder/precondition headers;
	// this keeps older owner routes that merely forward an idempotency key from
	// being misclassified as builder authoring requests.
	managed := request.BuilderTaskID != "" || request.ExpectedResourceHash != ""
	if !managed {
		value, err := execute()
		return ExecutionResult{Value: value}, err
	}
	if request.CapabilityKey == "" || request.ResourceID == "" || request.BuilderTaskID == "" {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, "backend.authoring.request_identity_required", nil, nil)
	}
	if request.IdempotencyKey == "" {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, idempotency.ErrorCodeMissingKey, nil, nil)
	}
	if request.ExpectedResourceHash == "" {
		request.ExpectedResourceHash = "empty"
	}
	if trustedTaskID := TrustedBuilderTaskID(ctx); trustedTaskID != "" && trustedTaskID != request.BuilderTaskID {
		return ExecutionResult{}, apperror.New(apperror.KindForbidden, "backend.authoring.builder_task_mismatch", nil, nil)
	}
	fingerprint, err := idempotency.Fingerprint(idempotency.FingerprintInput{
		UseCase: request.CapabilityKey + ".upsert", ResourceType: request.CapabilityKey, TargetID: request.ResourceID,
		Payload: request.Payload, Preconditions: map[string]any{"builder_task_id": request.BuilderTaskID, "expected_resource_hash": request.ExpectedResourceHash},
	})
	if err != nil {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, "backend.authoring.payload_invalid", err, nil)
	}
	return s.executeManaged(ctx, principal, request.IdempotencyKey, request.CapabilityKey+".upsert", request.CapabilityKey, request.ResourceID, fingerprint, func() (outcome, error) {
		value, found, loadErr := current()
		if loadErr != nil {
			return outcome{}, loadErr
		}
		actualHash, hashErr := resourceHash(request.CapabilityKey, request.ResourceID, value, found)
		if hashErr != nil {
			return outcome{}, hashErr
		}
		if request.ExpectedResourceHash != actualHash {
			return outcome{}, apperror.New(apperror.KindConflict, "backend.authoring.resource_hash_conflict", nil, map[string]string{"expected": request.ExpectedResourceHash, "actual": actualHash})
		}
		result, executeErr := execute()
		if executeErr != nil {
			return outcome{}, executeErr
		}
		persisted, persistedFound, loadErr := current()
		if loadErr != nil {
			return outcome{}, loadErr
		}
		persistedHash, hashErr := resourceHash(request.CapabilityKey, request.ResourceID, persisted, persistedFound)
		if hashErr != nil {
			return outcome{}, hashErr
		}
		if !persistedFound || persistedHash == "empty" {
			return outcome{}, apperror.New(apperror.KindUnavailable, "backend.authoring.resource_projection_unavailable", nil, nil)
		}
		return outcome{Value: result, ResourceHash: persistedHash}, nil
	})
}

func (s *Service) ExecuteCommand(ctx context.Context, request CommandRequest, principal identitymodel.Principal, authorize Authorize, execute Execute) (ExecutionResult, error) {
	request.UseCase = strings.TrimSpace(request.UseCase)
	request.ResourceType = strings.TrimSpace(request.ResourceType)
	request.ResourceID = strings.TrimSpace(request.ResourceID)
	request.IdempotencyKey = strings.TrimSpace(request.IdempotencyKey)
	if request.UseCase == "" || request.ResourceType == "" || request.ResourceID == "" {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, "backend.authoring.request_identity_required", nil, nil)
	}
	if request.IdempotencyKey == "" {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, idempotency.ErrorCodeMissingKey, nil, nil)
	}
	if authorize == nil || execute == nil {
		return ExecutionResult{}, apperror.New(apperror.KindUnavailable, "backend.authoring.owner_contract_unavailable", nil, nil)
	}
	if err := authorize(); err != nil {
		return ExecutionResult{}, err
	}
	fingerprint, err := idempotency.Fingerprint(idempotency.FingerprintInput{
		UseCase: request.UseCase, ResourceType: request.ResourceType, TargetID: request.ResourceID, Payload: request.Payload,
	})
	if err != nil {
		return ExecutionResult{}, apperror.New(apperror.KindBadRequest, "backend.authoring.payload_invalid", err, nil)
	}
	return s.executeManaged(ctx, principal, request.IdempotencyKey, request.UseCase, request.ResourceType, request.ResourceID, fingerprint, func() (outcome, error) {
		value, executeErr := execute()
		return outcome{Value: value}, executeErr
	})
}

type outcome struct {
	Value        any                `json:"value,omitempty"`
	ResourceHash string             `json:"resource_hash,omitempty"`
	ErrorKind    apperror.ErrorKind `json:"error_kind,omitempty"`
	ErrorCode    string             `json:"error_code,omitempty"`
}

func (s *Service) executeManaged(ctx context.Context, principal identitymodel.Principal, key, useCase, resourceType, targetID, fingerprint string, execute func() (outcome, error)) (ExecutionResult, error) {
	if s == nil || s.repository == nil {
		return ExecutionResult{}, apperror.New(apperror.KindUnavailable, idempotency.ErrorCodeReceiptUnavailable, nil, nil)
	}
	now := s.now().UTC()
	leaseOwner := strings.TrimSpace(s.newID())
	receipt := Receipt{
		ID: authoringReceiptID(principal.WorkspaceID, key), WorkspaceID: strings.TrimSpace(principal.WorkspaceID), UseCase: useCase,
		ResourceType: resourceType, TargetID: targetID, IdempotencyKey: key, RequestFingerprint: fingerprint,
		Status: idempotency.StatusProcessing, LeaseOwner: leaseOwner, LeaseExpiresAt: now.Add(defaultLeaseTTL), FencingToken: 1,
		CreatedAt: now, UpdatedAt: now,
	}
	claim, err := s.repository.Claim(ctx, receipt, defaultLeaseTTL)
	if err != nil {
		return ExecutionResult{}, apperror.New(apperror.KindInternal, idempotency.ErrorCodeReceiptUnavailable, err, nil)
	}
	switch claim.Decision {
	case idempotency.DecisionFingerprintConflict:
		return ExecutionResult{}, apperror.New(apperror.KindConflict, idempotency.ErrorCodeKeyReused, nil, nil)
	case idempotency.DecisionInProgress:
		return ExecutionResult{}, apperror.New(apperror.KindConflict, idempotency.ErrorCodeInProgress, nil, nil)
	case idempotency.DecisionReplay:
		return replayResult(claim.Receipt)
	case idempotency.DecisionAcquired:
		// continue below
	default:
		return ExecutionResult{}, apperror.New(apperror.KindInternal, idempotency.ErrorCodeReceiptUnavailable, nil, nil)
	}
	value, ownerErr := execute()
	if ownerErr != nil {
		value.ErrorKind = apperror.KindOf(ownerErr)
		value.ErrorCode = apperror.CodeOf(ownerErr)
	}
	encoded, marshalErr := json.Marshal(value)
	if marshalErr != nil {
		ownerErr = apperror.New(apperror.KindInternal, "backend.authoring.result_invalid", marshalErr, nil)
		encoded, _ = json.Marshal(outcome{ErrorKind: apperror.KindInternal, ErrorCode: "backend.authoring.result_invalid"})
	}
	status := idempotency.StatusSucceeded
	if ownerErr != nil {
		status = idempotency.StatusFailedTerminal
	}
	completed, completeErr := s.repository.Complete(ctx, Completion{
		ReceiptID: claim.Receipt.ID, WorkspaceID: claim.Receipt.WorkspaceID, LeaseOwner: claim.Receipt.LeaseOwner,
		FencingToken: claim.Receipt.FencingToken, Status: status, Result: encoded, CompletedAt: s.now().UTC(),
	})
	if completeErr != nil {
		return ExecutionResult{}, apperror.New(apperror.KindConflict, idempotency.ErrorCodeLeaseLost, completeErr, nil)
	}
	return ExecutionResult{Value: value.Value, OperationID: completed.ID, ResourceHash: value.ResourceHash}, ownerErr
}

func replayResult(receipt Receipt) (ExecutionResult, error) {
	var stored struct {
		Value        json.RawMessage    `json:"value"`
		ResourceHash string             `json:"resource_hash"`
		ErrorKind    apperror.ErrorKind `json:"error_kind"`
		ErrorCode    string             `json:"error_code"`
	}
	if err := json.Unmarshal(receipt.Result, &stored); err != nil {
		return ExecutionResult{}, apperror.New(apperror.KindInternal, "backend.authoring.receipt_result_invalid", err, nil)
	}
	var value any
	if len(stored.Value) != 0 && string(stored.Value) != "null" {
		if err := json.Unmarshal(stored.Value, &value); err != nil {
			return ExecutionResult{}, apperror.New(apperror.KindInternal, "backend.authoring.receipt_result_invalid", err, nil)
		}
	}
	result := ExecutionResult{Value: value, OperationID: receipt.ID, ResourceHash: stored.ResourceHash, Replayed: true}
	if receipt.Status == idempotency.StatusFailedTerminal {
		return result, apperror.New(stored.ErrorKind, stored.ErrorCode, nil, nil)
	}
	return result, nil
}

func resourceHash(capabilityKey, resourceID string, value any, found bool) (string, error) {
	if !found {
		return "empty", nil
	}
	return idempotency.Fingerprint(idempotency.FingerprintInput{UseCase: capabilityKey + ".resource", ResourceType: capabilityKey, TargetID: resourceID, Payload: value})
}

func authoringReceiptID(workspaceID, key string) string {
	sum := sha256.Sum256([]byte(strings.TrimSpace(workspaceID) + "\x00" + strings.TrimSpace(key)))
	return "identity_authoring_" + hex.EncodeToString(sum[:12])
}

package principalmodel

import (
	"errors"
	"strings"
)

var ErrWorkspaceIDRequired = errors.New("workspace id is required")
var ErrWorkspaceIDReserved = errors.New("default workspace id is reserved")
var ErrSystemScopeRequired = errors.New("valid system scope is required")
var ErrPrincipalScopeRequired = errors.New("authenticated principal scope is required")

// InstallationWorkspaceID is populated from the durable tenant installation
// marker before Runtime assembles any tenant-bound service or worker.
var InstallationWorkspaceID string

func ConfigureInstallationWorkspaceID(value string) error {
	id, err := NewWorkspaceID(value)
	if err != nil {
		return err
	}
	InstallationWorkspaceID = id.String()
	return nil
}

// WorkspaceID is a non-empty tenant boundary. Its value is intentionally
// private so Command/Query scope construction cannot bypass validation.
type WorkspaceID struct{ value string }

func NewWorkspaceID(value string) (WorkspaceID, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return WorkspaceID{}, ErrWorkspaceIDRequired
	}
	if strings.EqualFold(value, "default") {
		return WorkspaceID{}, ErrWorkspaceIDReserved
	}
	return WorkspaceID{value: value}, nil
}

func (id WorkspaceID) String() string { return id.value }
func (id WorkspaceID) Valid() bool    { return id.value != "" }

type CommandScope struct {
	workspace WorkspaceID
	system    SystemScope
}

func NewWorkspaceCommandScope(workspaceID string) (CommandScope, error) {
	id, err := NewWorkspaceID(workspaceID)
	if err != nil {
		return CommandScope{}, err
	}
	return CommandScope{workspace: id}, nil
}

func NewSystemCommandScope(system SystemScope) (CommandScope, error) {
	if !system.Valid() {
		return CommandScope{}, ErrSystemScopeRequired
	}
	return CommandScope{system: system}, nil
}

func (scope CommandScope) WorkspaceID() WorkspaceID { return scope.workspace }
func (scope CommandScope) SystemScope() SystemScope { return scope.system }
func (scope CommandScope) Valid() bool              { return scope.workspace.Valid() != scope.system.Valid() }

type QueryScope struct {
	workspace WorkspaceID
	system    SystemScope
}

func NewWorkspaceQueryScope(workspaceID string) (QueryScope, error) {
	id, err := NewWorkspaceID(workspaceID)
	if err != nil {
		return QueryScope{}, err
	}
	return QueryScope{workspace: id}, nil
}

func NewSystemQueryScope(system SystemScope) (QueryScope, error) {
	if !system.Valid() {
		return QueryScope{}, ErrSystemScopeRequired
	}
	return QueryScope{system: system}, nil
}

func (scope QueryScope) WorkspaceID() WorkspaceID { return scope.workspace }
func (scope QueryScope) SystemScope() SystemScope { return scope.system }
func (scope QueryScope) Valid() bool              { return scope.workspace.Valid() != scope.system.Valid() }

func CommandScopeForPrincipal(principal Principal) (CommandScope, error) {
	if !principal.Known {
		return CommandScope{}, ErrPrincipalScopeRequired
	}
	if principal.SystemScope.Valid() {
		return NewSystemCommandScope(principal.SystemScope)
	}
	return NewWorkspaceCommandScope(principal.WorkspaceID)
}

func QueryScopeForPrincipal(principal Principal) (QueryScope, error) {
	if !principal.Known {
		return QueryScope{}, ErrPrincipalScopeRequired
	}
	if principal.SystemScope.Valid() {
		return NewSystemQueryScope(principal.SystemScope)
	}
	return NewWorkspaceQueryScope(principal.WorkspaceID)
}
package runtimehost

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"sync"

	identitysdk "github.com/domainry/domainry-identity-sdk"
	identityhttpapi "github.com/domainry/domainry-identity-sdk/httpapi"
	"github.com/domainry/domainry-runtime/runtime/bootstrap"
	manifestmodel "github.com/domainry/domainry-runtime/runtime/domain/manifest/model"
	workspaceprovisionmodel "github.com/domainry/domainry-runtime/runtime/domain/workspaceprovision/model"
	"github.com/domainry/domainry-runtime/runtime/infrastructure/persistence/database/workspaceprovision"
	"github.com/domainry/domainry-runtime/runtime/platform/config"
)

type projectTenantManager struct {
	mu        sync.Mutex
	cfg       config.Config
	factory   identitysdk.Factory
	database  *bootstrap.ProjectDatabase
	handle    identitysdk.DatabaseHandle
	bootstrap identitysdk.BootstrapBinding
	binding   identitysdk.Binding
	adapters  []identityhttpapi.Adapter
}

func newProjectTenantManager(ctx context.Context, cfg config.Config, factory identitysdk.Factory, database *bootstrap.ProjectDatabase, handle identitysdk.DatabaseHandle) (*projectTenantManager, error) {
	manager := &projectTenantManager{cfg: cfg, factory: factory, database: database, handle: handle}
	installation, found, err := workspaceprovision.LoadInstallation(ctx, database)
	if err != nil {
		return nil, err
	}
	if found {
		if err := manager.bindInitializedIdentity(ctx, installation); err != nil {
			return nil, err
		}
		return manager, nil
	}
	bootstrapFactory, ok := factory.(identitysdk.BootstrapDatabaseFactory)
	if !ok {
		return nil, fmt.Errorf("initial tenant requires an embedded Identity BootstrapDatabaseFactory")
	}
	bootstrapBinding, err := bootstrapFactory.OpenBootstrapWithDatabase(ctx, identitysdk.ApplicationKey(cfg.IdentityAudience), handle)
	if err != nil {
		return nil, fmt.Errorf("open initial tenant Identity bootstrap: %w", err)
	}
	if bootstrapBinding == nil {
		return nil, fmt.Errorf("Identity bootstrap factory returned no binding")
	}
	manager.bootstrap = bootstrapBinding
	return manager, nil
}

func (manager *projectTenantManager) Activate(ctx context.Context, manifest manifestmodel.ManifestSchema) error {
	manager.mu.Lock()
	defer manager.mu.Unlock()
	if manager.binding != nil {
		return nil
	}
	if manager.bootstrap == nil {
		return fmt.Errorf("initial tenant bootstrap is unavailable")
	}
	if err := manager.database.EnsureRuntimeSchema(ctx); err != nil {
		return fmt.Errorf("prepare application schema before initial tenant: %w", err)
	}
	request, password, err := initialTenantRequest(manager.cfg)
	if err != nil {
		return err
	}
	result, err := workspaceprovision.NewTenantInitializationStore(manager.database, manager.bootstrap, manifest).Initialize(ctx, request, password)
	if err != nil {
		return fmt.Errorf("initialize first tenant atomically: %w", err)
	}
	if err := manager.bootstrap.Close(context.WithoutCancel(ctx)); err != nil {
		return fmt.Errorf("close Identity bootstrap after initial tenant: %w", err)
	}
	manager.bootstrap = nil
	installation, found, err := workspaceprovision.LoadInstallation(ctx, manager.database)
	if err != nil {
		return fmt.Errorf("verify committed initial tenant: %w", err)
	}
	if !found || installation.WorkspaceID != result.WorkspaceID || installation.TenantRegistryID != result.TenantRegistryID {
		return fmt.Errorf("verify committed initial tenant: committed marker does not match transaction result")
	}
	return manager.bindInitializedIdentity(ctx, installation)
}

func initialTenantRequest(cfg config.Config) (workspaceprovisionmodel.Request, string, error) {
	configuration := map[string]any{}
	rawConfiguration := strings.TrimSpace(cfg.InitialTenantStoreConfiguration)
	if rawConfiguration == "" {
		rawConfiguration = "{}"
	}
	if err := json.Unmarshal([]byte(rawConfiguration), &configuration); err != nil {
		return workspaceprovisionmodel.Request{}, "", fmt.Errorf("INITIAL_TENANT_STORE_CONFIGURATION must be a JSON object: %w", err)
	}
	if configuration == nil {
		return workspaceprovisionmodel.Request{}, "", fmt.Errorf("INITIAL_TENANT_STORE_CONFIGURATION must be a JSON object")
	}
	password := strings.TrimSpace(cfg.InitialManagementPassword)
	if password == "" {
		return workspaceprovisionmodel.Request{}, "", fmt.Errorf("INITIAL_MANAGEMENT_PASSWORD or INITIAL_MANAGEMENT_PASSWORD_FILE is required before tenant initialization")
	}
	return workspaceprovisionmodel.Request{
		RequestID: strings.TrimSpace(cfg.InitialTenantRequestID), TenantCode: strings.TrimSpace(cfg.InitialTenantCode),
		TenantName: strings.TrimSpace(cfg.InitialTenantName), AdminLoginID: strings.TrimSpace(cfg.InitialManagementLoginID),
		AdminName: strings.TrimSpace(cfg.InitialManagementName), StoreConfiguration: configuration,
	}, password, nil
}

func (manager *projectTenantManager) bindInitializedIdentity(ctx context.Context, installation workspaceprovision.Installation) error {
	cfg, err := resolveInstallationConfig(manager.cfg, installation)
	if err != nil {
		return err
	}
	binding, adapters, err := openProjectIdentity(ctx, cfg, manager.factory, manager.handle)
	if err != nil {
		return err
	}
	manager.cfg, manager.binding, manager.adapters = cfg, binding, adapters
	return nil
}

func resolveInstallationConfig(cfg config.Config, installation workspaceprovision.Installation) (config.Config, error) {
	expected := map[string]string{
		"IDENTITY_WORKSPACE_ID": installation.WorkspaceID,
		// Embedded Identity currently issues browser access bundles with both
		// tenant_id and workspace_id set to the initialized workspace ID. The
		// embedded Notification binding validates both fields against its
		// application scope, so it must use the same principal scope. The
		// tenant registry ID remains the Runtime provisioning identity; it is
		// not the tenant claim exposed by embedded Identity sessions.
		"NOTIFICATION_TENANT_ID":    installation.WorkspaceID,
		"NOTIFICATION_WORKSPACE_ID": installation.WorkspaceID,
	}
	configured := map[string]string{
		"IDENTITY_WORKSPACE_ID":     cfg.IdentityWorkspaceID,
		"NOTIFICATION_TENANT_ID":    cfg.NotificationTenantID,
		"NOTIFICATION_WORKSPACE_ID": cfg.NotificationWorkspaceID,
	}
	for name, actual := range configured {
		if actual = strings.TrimSpace(actual); actual != "" && actual != expected[name] {
			return config.Config{}, fmt.Errorf("%s=%q conflicts with initialized tenant %q", name, actual, expected[name])
		}
	}
	cfg.IdentityWorkspaceID = installation.WorkspaceID
	cfg.NotificationTenantID, cfg.NotificationWorkspaceID = installation.WorkspaceID, installation.WorkspaceID
	return cfg, nil
}

func (manager *projectTenantManager) Config() config.Config {
	manager.mu.Lock()
	defer manager.mu.Unlock()
	return manager.cfg
}

func (manager *projectTenantManager) Binding() identitysdk.Binding {
	manager.mu.Lock()
	defer manager.mu.Unlock()
	return manager.binding
}

func (manager *projectTenantManager) Adapters() []identityhttpapi.Adapter {
	manager.mu.Lock()
	defer manager.mu.Unlock()
	return append([]identityhttpapi.Adapter(nil), manager.adapters...)
}

func (manager *projectTenantManager) Close(ctx context.Context) error {
	manager.mu.Lock()
	defer manager.mu.Unlock()
	if manager.binding != nil {
		return manager.binding.Close(ctx)
	}
	if manager.bootstrap != nil {
		return manager.bootstrap.Close(ctx)
	}
	return nil
}
