)

// ScanOverdue implements the project-owned lead.scan_overdue Handler.
func ScanOverdue(ctx context.Context, caps capabilities.ScanOverdueCapabilities, input capabilities.ScanOverdueInput) (capabilities.ScanOverdueOutput, error) {
	_ = input
	now := time.Now().UTC()
	businessDate := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	cutoff := now.Add(-7 * 24 * time.Hour)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
		WhereStatusEqual(schema.LeadStatus("contacted")).
		WhereStatusChangedAtLessThanOrEqual(cutoff).
		OrderByIDAscending().
		Page(1, 200))
	if err != nil {
		return capabilities.ScanOverdueOutput{}, err
	}
	if len(leads) == 0 {
		return capabilities.ScanOverdueOutput{}, nil
	}
	queries := make([]data.ReminderOccurrenceQuery, len(leads))
	for i, lead := range leads {
		key := string(lead.ID) + ":" + businessDate.Format("2006-01-02")
		queries[i] = data.NewReminderOccurrenceQuery().WhereDeduplicationKeyEqual(key)
	}
	existing, err := caps.ReminderOccurrence.ExistsBatch(ctx, queries)
	if err != nil {
		return capabilities.ScanOverdueOutput{}, err
	}
	creates := make([]schema.CreateReminderOccurrence, 0, len(leads))
	intents := make([]capabilities.ScanOverdueNotificationIntent, 0, len(leads))
	for i, lead := range leads {
		if existing[i] {
			continue
		}
		key := string(lead.ID) + ":" + businessDate.Format("2006-01-02")
		creates = append(creates, schema.CreateReminderOccurrence{
			DeduplicationKey: key,
			LeadID:           schema.NewReminderOccurrenceLeadIDReference(lead.ID),
			RecipientUser:    lead.ResponsibleUser,
			ReminderDate:     businessDate,
		})
		company := lead.CompanyName
		intents = append(intents, capabilities.ScanOverdueNotificationIntent{
			EventType:        "lead.followup_overdue",
			SourceEventID:    "followup-overdue:" + key,
			RecipientUserIDs: []string{lead.ResponsibleUser},
			SubjectObjectKey: "lead",
			SubjectRecordID:  string(lead.ID),
			SubjectVersion:   lead.UpdatedAt,
			DedupeKey:        "followup-overdue:" + key,
			GroupKey:         "lead:" + string(lead.ID),
			OccurredAt:       now,
			Variables:        []capabilities.ScanOverdueNotificationVariable{{Key: "company_name", StringValue: &company}},
		})
	}
	if len(creates) == 0 {
		return capabilities.ScanOverdueOutput{}, nil
	}
	created, err := caps.ReminderOccurrence.CreateBatch(ctx, creates)
	if err != nil {
		return capabilities.ScanOverdueOutput{}, err
	}
	if len(created) != len(creates) {
		return capabilities.ScanOverdueOutput{}, &capabilities.BusinessError{Code: "lead.scan_overdue.incomplete_receipts"}
	}
	notificationIDs, err := caps.Notifications.DispatchBatch(ctx, intents)
	if err != nil {
		return capabilities.ScanOverdueOutput{}, err
	}
	if len(notificationIDs) != len(intents) {
		return capabilities.ScanOverdueOutput{}, &capabilities.BusinessError{Code: "lead.scan_overdue.incomplete_notifications"}
	}
	return capabilities.ScanOverdueOutput{}, nil
}
