{
  "modules": {
    "crm": {
      "features": {
        "crm_conversion": {
          "requirement": {
            "statement": "Qualified leads convert exactly once, with director approval at or above 100000.00 and atomic customer, decision, audit, and notification outcomes.",
            "acceptance": [
              "Amounts below 100000.00 convert directly and create exactly one immutable customer.",
              "Amounts at or above 100000.00 create one pending approval for a director to approve or reject.",
              "Approval atomically converts and creates one customer; rejection preserves qualified state and a reason; both notify the requester."
            ]
          },
          "objects": {
            "conversion_request": {
              "description": "The single governed conversion decision for a large qualified lead.",
              "fields": {
                "lead_id": "relation!->lead;on_delete=restrict",
                "amount_snapshot": "currency!;precision=19;scale=2;currency=CNY;rounding=half_even",
                "threshold_snapshot": "currency!;precision=19;scale=2;currency=CNY;rounding=half_even",
                "status": "select![pending:待审批|approved:已批准|rejected:已拒绝]=pending",
                "rejection_reason": "long_text;min_length=1;max_length=1000",
                "decided_at": "datetime",
                "decided_by": "user",
                "requester_user": "user!"
              }
            },
            "customer": {
              "description": "An immutable customer snapshot created by a successful lead conversion.",
              "fields": {
                "company_name": "text!;min_length=1;max_length=200",
                "contact_name": "text;max_length=120",
                "amount": "currency!;precision=19;scale=2;currency=CNY;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound:外呼]",
                "source_lead_id": "relation!->lead;on_delete=restrict"
              }
            }
          },
          "notification_event_types": {
            "lead.conversion_approved": {
              "source": "project",
              "category": "business",
              "default_severity": "info",
              "mandatory_in_app": true,
              "template_key": "lead_conversion_approved",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化已批准",
                  "body": "线索「{{company_name}}」的转化已批准并创建客户。",
                  "action_labels": {
                    "open_lead": "查看线索"
                  }
                }
              },
              "variables": {
                "company_name": "text!"
              },
              "actions": {
                "open_lead": {
                  "resource_type": "project_record",
                  "route_key": "business.leads.my"
                }
              }
            },
            "lead.conversion_rejected": {
              "source": "project",
              "category": "business",
              "default_severity": "warning",
              "mandatory_in_app": true,
              "template_key": "lead_conversion_rejected",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化已拒绝",
                  "body": "线索「{{company_name}}」的转化已拒绝：{{rejection_reason}}",
                  "action_labels": {
                    "open_lead": "查看线索"
                  }
                }
              },
              "variables": {
                "company_name": "text!",
                "rejection_reason": "text!"
              },
              "actions": {
                "open_lead": {
                  "resource_type": "project_record",
                  "route_key": "business.leads.my"
                }
              }
            }
          },
          "actions": {
            "lead.request_conversion": {
              "kind": "record_operation",
              "preconditions": ["status == qualified"],
              "handler": {
                "reason": "Conversion must atomically compare the exact amount snapshot, enforce one outcome, and either create a pending request or convert with one customer.",
                "access": {
                  "lead": ["get_for_update", "conditional_update"],
                  "conversion_request": ["list", "create"],
                  "customer": ["optional", "create"]
                }
              }
            },
            "conversion_request.approve": {
              "kind": "record_operation",
              "preconditions": ["status == pending"],
              "handler": {
                "reason": "Director approval must commit the decision, lead conversion, one immutable customer, and requester notification as one guarded transaction.",
                "access": {
