// TestBF01LeadLifecycleAndScope proves fresh creation defaults, owner/department facts,
// ordered lifecycle transitions, and that a denied same-record write leaves state unchanged.
func TestBF01LeadLifecycleAndScope(t *testing.T) {
	repo := &leadRepository{nextStatuses: []schema.LeadStatus{"contacted", "qualified"}}
	exec := leadExec{user: "rep-east-1", org: "org-east", id: "lead-created"}
	_, err := crm.CreateLead(t.Context(), capabilities.CreateLeadCapabilities{Execution: exec, Lead: repo}, capabilities.CreateLeadInput{CompanyName: "East Acme", EstimatedAmount: "80000.00", Source: "website"})
	if err != nil {
		t.Fatal(err)
	}
	if repo.created.ResponsibleUser == nil || *repo.created.ResponsibleUser != exec.user || repo.created.Department == nil || string(repo.created.Department.ID()) != exec.org || repo.created.Status != "new" {
		t.Fatalf("principal defaults not persisted: %+v", repo.created)
	}
	if _, err = crm.MarkContacted(t.Context(), capabilities.MarkContactedCapabilities{Execution: exec, Lead: repo}, capabilities.MarkContactedInput{}); err != nil {
		t.Fatal(err)
	}
	if _, err = crm.MarkQualified(t.Context(), capabilities.MarkQualifiedCapabilities{Execution: exec, Lead: repo}, capabilities.MarkQualifiedInput{}); err != nil {
		t.Fatal(err)
	}
	before := repo.record.Status
	denied := &leadRepository{record: repo.record, readErr: errDenied}
	if _, err = crm.UpdateDetails(t.Context(), capabilities.UpdateDetailsCapabilities{Execution: leadExec{user: "peer-east", org: "org-east", id: repo.record.ID}, Lead: denied}, capabilities.UpdateDetailsInput{}); !errors.Is(err, errDenied) {
		t.Fatalf("want owner-scope denial, got %v", err)
	}
	if denied.record.Status != before {
		t.Fatalf("denial changed status: %s -> %s", before, denied.record.Status)
	}
}

// TestBF02DirectConversionIdempotency starts from one qualified sub-threshold lead,
// converts it atomically, then replays against the terminal record and proves no second customer.
func TestBF02DirectConversionIdempotency(t *testing.T) {
	leads := &leadRepository{record: qualifiedLead("lead-small", "99999.99", "rep-east-1"), nextStatuses: []schema.LeadStatus{"converted"}}
	customers := &customerRepository{}
	caps := capabilities.RequestConversionCapabilities{Execution: leadExec{user: "rep-east-1", org: "org-east", id: "lead-small"}, Lead: leads, Customer: customers, ConversionRequest: &conversionRepository{}}
	if _, err := crm.RequestConversion(t.Context(), caps, capabilities.RequestConversionInput{}); err != nil {
		t.Fatal(err)
	}
	if leads.record.Status != "converted" || len(customers.creates) != 1 || customers.creates[0].SourceLeadID.ID() != "lead-small" {
		t.Fatalf("bad direct conversion: status=%s customers=%d", leads.record.Status, len(customers.creates))
	}
	if _, err := crm.RequestConversion(t.Context(), caps, capabilities.RequestConversionInput{}); err == nil {
		t.Fatal("terminal replay unexpectedly succeeded")
	}
	if len(customers.creates) != 1 {
		t.Fatalf("replay created %d customers", len(customers.creates))
	}
}

// TestBF03LargeApprovalAccepted creates a pending large request and proves director approval
// yields one converted lead, one customer, one approved decision, and a requester-owned notice.
func TestBF03LargeApprovalAccepted(t *testing.T) {
	leads := &leadRepository{record: qualifiedLead("lead-large", "100000.00", "rep-east-1"), nextStatuses: []schema.LeadStatus{"converted"}}
	requests := &conversionRepository{record: pendingRequest("request-large", "lead-large", "rep-east-1"), nextStatus: "approved"}
	customers := &customerRepository{}
	notices := &approveNotifications{}
	_, err := crm.Approve(t.Context(), capabilities.ApproveCapabilities{Execution: conversionExec{user: "director", id: "request-large"}, ConversionRequest: requests, Customer: customers, Lead: leads, Notifications: notices}, capabilities.ApproveInput{})
	if err != nil {
		t.Fatal(err)
	}
	if leads.record.Status != "converted" || requests.record.Status != "approved" || len(customers.creates) != 1 || len(notices.intents) != 1 {
		t.Fatalf("approval terminal facts missing: lead=%s request=%s customers=%d notices=%d", leads.record.Status, requests.record.Status, len(customers.creates), len(notices.intents))
	}
	if got := notices.intents[0].RecipientUserIDs; len(got) != 1 || got[0] != "rep-east-1" {
		t.Fatalf("notice recipient = %v", got)
	}
}

// TestBF04LargeApprovalRejected proves rejection retains qualified lead state, creates no
// customer, records one terminal decision, and notifies only the initiating representative.
func TestBF04LargeApprovalRejected(t *testing.T) {
	leads := &leadRepository{record: qualifiedLead("lead-reject", "250000.00", "rep-north-1")}
	requests := &conversionRepository{record: pendingRequest("request-reject", "lead-reject", "rep-north-1"), nextStatus: "rejected"}
	notices := &rejectNotifications{}
	_, err := crm.Reject(t.Context(), capabilities.RejectCapabilities{Execution: conversionExec{user: "director", id: "request-reject"}, ConversionRequest: requests, Lead: leads, Notifications: notices}, capabilities.RejectInput{RejectionReason: "风险过高"})
	if err != nil {
		t.Fatal(err)
	}
	if leads.record.Status != "qualified" || requests.record.Status != "rejected" || len(notices.intents) != 1 || notices.intents[0].RecipientUserIDs[0] != "rep-north-1" {
		t.Fatalf("bad rejection terminal facts: lead=%s request=%s notices=%v", leads.record.Status, requests.record.Status, notices.intents)
	}
}

// TestBF05DepartmentScopesPaginationAndMenus binds the same-record org/all scope contrast
// and role-specific Business Workspace entrypoints to the immutable project model.
func TestBF05DepartmentScopesPaginationAndMenus(t *testing.T) {
	access := mustRead(t, "../../model/30-crm-access.json")
	workspace := mustRead(t, "../../model/60-crm-workspace.json")
	for _, fact := range [][]byte{[]byte(`"lead.read;org"`), []byte(`"lead.update_details;owner"`), []byte(`"lead.read;all"`)} {
		if !bytes.Contains(access, fact) {
			t.Fatalf("missing scope fact %s", fact)
		}
	}
	for _, fact := range [][]byte{[]byte(`"my_leads"`), []byte(`"audience": "sales_rep"`), []byte(`"all_leads"`), []byte(`"crm_reports"`), []byte(`"audience": "sales_director"`)} {
		if !bytes.Contains(workspace, fact) {
			t.Fatalf("missing entrypoint fact %s", fact)
		}
	}
}

// TestBF06OverdueReminderDedupRestart starts with one overdue contacted lead, runs the
// bounded scan twice, and proves one durable occurrence/notice addressed to its owner.
func TestBF06OverdueReminderDedupRestart(t *testing.T) {
	owner := "rep-east-1"
	leads := &leadRepository{listed: []schema.Lead{{
		ID: "lead-overdue", UpdatedAt: "lead-v1", CompanyName: "Overdue Co",
		ResponsibleUser: &owner, Status: "contacted",
		StatusChangedAt: time.Now().UTC().Add(-8 * 24 * time.Hour),
	}}}
	occurrences := &reminderRepository{}
	notices := &scanNotifications{}
	caps := capabilities.ScanOverdueCapabilities{Execution: leadExec{user: "scheduler", org: "org-system"}, Lead: leads, ReminderOccurrence: occurrences, Notifications: notices}
	if _, err := crm.ScanOverdue(t.Context(), caps, capabilities.ScanOverdueInput{}); err != nil {
		t.Fatal(err)
	}
	if _, err := crm.ScanOverdue(t.Context(), caps, capabilities.ScanOverdueInput{}); err != nil {
		t.Fatal(err)
	}
	if len(occurrences.creates) != 1 || len(notices.intents) != 1 || notices.intents[0].RecipientUserIDs[0] != "rep-east-1" {
		t.Fatalf("dedupe/recipient failure: occurrences=%d notices=%v", len(occurrences.creates), notices.intents)
	}
}

// TestBF07FunnelReportAuthorization proves the governed query is bounded and uses the
// accepted count/sum grouping while only the director is an audience role.
func TestBF07FunnelReportAuthorization(t *testing.T) {
	sql := mustRead(t, "../../reports/crm_funnel.sql")
	model := mustRead(t, "../../model/50-crm-reporting.json")
	for _, fact := range [][]byte{[]byte("COUNT(l.id)"), []byte("SUM(l.estimated_amount)"), []byte("GROUP BY l.status"), []byte("LIMIT 5")} {
		if !bytes.Contains(sql, fact) {
			t.Fatalf("funnel query missing %q", fact)
		}
	}
	if !bytes.Contains(model, []byte(`"audience_roles": ["sales_director"]`)) || bytes.Contains(model, []byte(`"audience_roles": ["sales_rep"]`)) {
		t.Fatal("funnel audience is not director-only")
	}
}

// TestBF08ControlledLeadCSVExport proves the detail source is bounded and the exact
// director-only all-scope export grant exists; Runtime verify owns offline job/restart proof.
func TestBF08ControlledLeadCSVExport(t *testing.T) {
	sql := mustRead(t, "../../reports/crm_lead_detail_export.sql")
	access := mustRead(t, "../../model/30-crm-access.json")
	reports := mustRead(t, "../../model/50-crm-reporting.json")
	if !bytes.Contains(sql, []byte("LIMIT 1000")) || !bytes.Contains(access, []byte(`"lead.export;all"`)) || !bytes.Contains(reports, []byte(`"crm_lead_detail_export"`)) {
		t.Fatal("controlled export contract is incomplete")
	}
	if bytes.Contains(access, []byte(`"lead.export;org"`)) {
		t.Fatal("sales representative unexpectedly has export permission")
	}
}

func qualifiedLead(id schema.LeadID, amount, owner string) schema.Lead {
	department := schema.NewLeadDepartmentReference("org-east")
	return schema.Lead{ID: id, UpdatedAt: "lead-v1", CompanyName: "Qualified Co", Department: &department, EstimatedAmount: schema.LeadEstimatedAmount(amount), ResponsibleUser: &owner, Source: "referral", Status: "qualified", StatusChangedAt: time.Now().UTC()}
}

func pendingRequest(id schema.ConversionRequestID, leadID schema.LeadID, requester string) schema.ConversionRequest {
	return schema.ConversionRequest{ID: id, UpdatedAt: "request-v1", AmountSnapshot: "100000.00", LeadID: schema.NewConversionRequestLeadIDReference(leadID), RequesterUser: requester, Status: "pending", ThresholdSnapshot: "100000.00"}
}

func mustRead(t *testing.T, path string) []byte {
	t.Helper()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return content
}

