func assertManagedRuntime(t *testing.T) {
	t.Helper()
	baseURL := strings.TrimRight(os.Getenv("DOMAINRY_MANAGED_RUNTIME_URL"), "/")
	if baseURL == "" {
		return
	}
	phase := os.Getenv("DOMAINRY_MANAGED_RUNTIME_PHASE")
	if phase != "initial" && phase != "restart" {
		t.Fatalf("invalid managed Runtime phase %q", phase)
	}
	workspaceID := os.Getenv("CRM_TEST_WORKSPACE_ID")
	password := os.Getenv("CRM_TEST_ADMIN_PASSWORD")
	if workspaceID == "" || password == "" {
		t.Fatal("managed Runtime acceptance credentials are required")
	}
	loginBody := map[string]any{
		"workspace_id": workspaceID,
		"application_key": "domainry-runtime",
		"login": "admin@example.com",
		"password": password,
	}
	status, body := runtimeRequest(t, baseURL, workspaceID, "", http.MethodPost, "/api/auth/login", loginBody, "")
	if status != http.StatusOK {
		t.Fatalf("managed Runtime login: status=%d body=%s", status, body)
	}
	var login struct {
		AccessToken string `json:"access_token"`
		Session *struct { AccessToken string `json:"access_token"` } `json:"session"`
	}
	if err := json.Unmarshal(body, &login); err != nil {
		t.Fatalf("decode managed Runtime login: %v", err)
	}
	token := login.AccessToken
	if token == "" && login.Session != nil {
		token = login.Session.AccessToken
	}
	if token == "" {
		t.Fatalf("managed Runtime login did not return an access token: %s", body)
	}
	status, body = runtimeRequest(t, baseURL, workspaceID, token, http.MethodGet, "/api/records/lead?page=1&page_size=10", nil, "")
	if status != http.StatusOK || !bytes.Contains(body, []byte(`"items"`)) {
		t.Fatalf("managed Runtime durable lead readback: status=%d body=%s", status, body)
	}
	status, body = runtimeRequest(t, baseURL, workspaceID, token, http.MethodGet, "/api/records/lead/actions", nil, "")
	if status != http.StatusOK || !bytes.Contains(body, []byte("lead.create_lead")) {
		t.Fatalf("managed Runtime Action catalog: status=%d body=%s", status, body)
	}
	for _, name := range []string{"DOMAINRY_MANAGED_RUNTIME_DELIVERY_ID", "DOMAINRY_MANAGED_RUNTIME_PACKAGE_RECEIPT_SHA256", "DOMAINRY_MANAGED_RUNTIME_VERIFICATION_RECEIPT_SHA256", "DOMAINRY_MANAGED_RUNTIME_PROJECT_SOURCE_SHA256", "DOMAINRY_MANAGED_RUNTIME_DATABASE_IDENTITY_SHA256"} {
		if strings.TrimSpace(os.Getenv(name)) == "" {
			t.Fatalf("managed Runtime evidence %s is empty", name)
		}
	}
}

func runtimeRequest(t *testing.T, baseURL, workspaceID, token, method, path string, payload any, idempotencyKey string) (int, []byte) {
	t.Helper()
	var reader io.Reader
	if payload != nil {
		encoded, err := json.Marshal(payload)
		if err != nil {
			t.Fatal(err)
		}
		reader = bytes.NewReader(encoded)
	}
	req, err := http.NewRequestWithContext(t.Context(), method, baseURL+path, reader)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Workspace-ID", workspaceID)
	req.Header.Set("X-Request-ID", fmt.Sprintf("bf-%s-%d", strings.ToLower(t.Name()), time.Now().UnixNano()))
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", idempotencyKey)
	}
	response, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("managed Runtime request %s %s: %v", method, path, err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	return response.StatusCode, body
}
